function createPoll(){if(!pollQ.trim()){alert("Poll ka sawal likho!");return}const opts=pollOpts.filter(o=>o.trim()).map(t=>({text:t.trim(),votes:0,voters:[]}));if(opts.length<2){alert("Kam se kam 2 options likho!");return}pushMsg({type:"poll",question:pollQ,options:opts,multi:pollMulti,myVote:[]});setShowPoll(false);setPollQ("");setPollOpts(["",""]);setPollMulti(false);setShowAttach(false)}
function votePoll(msgIdx:number,optIdx:number){const nm=[...msgs];const m={...nm[msgIdx]};const opts=m.options.map((o:any)=>({...o,voters:[...(o.voters||[])]}));const me="Adeel";if(m.multi){const my=(m.myVote||[]);if(my.includes(optIdx)){m.myVote=my.filter((x:number)=>x!==optIdx);opts[optIdx].votes=Math.max(0,opts[optIdx].votes-1);opts[optIdx].voters=opts[optIdx].voters.filter((v:string)=>v!==me)}else{m.myVote=[...my,optIdx];opts[optIdx].votes+=1;opts[optIdx].voters=[...opts[optIdx].voters,me]}}else{if(m.myVote&&m.myVote[0]===optIdx){opts[optIdx].votes=Math.max(0,opts[optIdx].votes-1);opts[optIdx].voters=opts[optIdx].voters.filter((v:string)=>v!==me);m.myVote=[]}else{if(m.myVote&&m.myVote.length){const prev=m.myVote[0];opts[prev].votes=Math.max(0,opts[prev].votes-1);opts[prev].voters=opts[prev].voters.filter((v:string)=>v!==me)}m.myVote=[optIdx];opts[optIdx].votes+=1;opts[optIdx].voters=[...opts[optIdx].voters,me]}}m.options=opts;nm[msgIdx]=m;setMsgs(nm)}
