const [editTextSize,setEditTextSize]=useState(28);
const editCanvasRef=useRef<any>(null);const editImgRef=useRef<any>(null);const isDrawing=useRef(false);const lastDraw=useRef<any>(null);
function openEditor(src:string){setEditSrc(src);setEditFilter("None");setEditCrop("Full");setEditText("");setEditTool("crop");setShowEditor(true);setShowLiveCamera(false);setShowAttach(false);setShowCameraChoice(false);setTimeout(()=>{drawEditCanvas()},100)}
function drawEditCanvas(){const c=editCanvasRef.current;if(!c||!editSrc)return;const img=new Image();img.crossOrigin="anonymous";img.onload=()=>{editImgRef.current=img;c.width=img.width;c.height=img.height;redrawEdit()};img.src=editSrc}
function redrawEdit(){const c=editCanvasRef.current;const img=editImgRef.current;if(!c||!img)return;const ctx=c.getContext("2d");ctx.clearRect(0,0,c.width,c.height);ctx.save();if(editFilter==="Warm")ctx.filter="sepia(0.12) saturate(1.08) brightness(1.02)";else if(editFilter==="Cool")ctx.filter="hue-rotate(8deg) saturate(1.05)";else if(editFilter==="Black & White")ctx.filter="grayscale(1)";else if(editFilter==="Vivid")ctx.filter="saturate(1.15) contrast(1.03)";else if(editFilter==="Soft")ctx.filter="brightness(1.05) contrast(0.98) saturate(0.95)";else if(editFilter==="Natural")ctx.filter="saturate(1.05) brightness(1.03)";else ctx.filter="none";ctx.drawImage(img,0,0);ctx.restore();if(editText){ctx.font="bold "+editTextSize+"px Arial";ctx.fillStyle=editTextColor;ctx.strokeStyle="rgba(0,0,0,0.7)";ctx.lineWidth=3;ctx.strokeText(editText,20,50);ctx.fillText(editText,20,50)}}
useEffect(()=>{if(showEditor)redrawEdit()},[editFilter,editText,editTextColor,editTextSize,editCrop]);
function onDrawStart(e:any){if(editTool!=="draw")return;isDrawing.current=true;const r=editCanvasRef.current.getBoundingClientRect();const x=(e.touches?e.touches[0].clientX:e.clientX)-r.left;const y=(e.touches?e.touches[0].clientY:e.clientY)-r.top;const sx=x/r.width*editCanvasRef.current.width;const sy=y/r.height*editCanvasRef.current.height;lastDraw.current={x:sx,y:sy}}
function onDrawMove(e:any){if(!isDrawing.current||editTool!=="draw")return;const r=editCanvasRef.current.getBoundingClientRect();const x=(e.touches?e.touches[0].clientX:e.clientX)-r.left;const y=(e.touches?e.touches[0].clientY:e.clientY)-r.top;const sx=x/r.width*editCanvasRef.current.width;const sy=y/r.height*editCanvasRef.current.height;const ctx=editCanvasRef.current.getContext("2d");ctx.strokeStyle=drawColor;ctx.lineWidth=drawSize;ctx.lineCap="round";ctx.beginPath();ctx.moveTo(lastDraw.current.x,lastDraw.current.y);ctx.lineTo(sx,sy);ctx.stroke();lastDraw.current={x:sx,y:sy}}
function onDrawEnd(){isDrawing.current=false}
function applyCrop(){const c=editCanvasRef.current;const img=editImgRef.current;if(!c||!img)return;let sx=0,sy=0,sw=img.width,sh=img.height;if(editCrop==="Square"){const s=Math.min(sw,sh);sx=(sw-s)/2;sy=(sh-s)/2;sw=s;sh=s}if(editCrop==="16:9"){const th=sw*9/16;if(th<=sh){sy=(sh-th)/2;sh=th}else{const tw=sh*16/9;sx=(sw-tw)/2;sw=tw}}if(editCrop==="4:3"){const th=sw*3/4;if(th<=sh){sy=(sh-th)/2;sh=th}else{const tw=sh*4/3;sx=(sw-tw)/2;sw=tw}}const tmp=document.createElement("canvas");tmp.width=sw;tmp.height=sh;const tctx=tmp.getContext("2d");tctx.drawImage(c,sx,sy,sw,sh,0,0,sw,sh);return tmp.toDataURL("image/jpeg",0.92)}
function sendEditedPhoto(){let finalUrl="";if(editCrop!=="Full"){finalUrl=applyCrop()||editCanvasRef.current.toDataURL("image/jpeg",0.92)}else{finalUrl=editCanvasRef.current.toDataURL("image/jpeg",0.92)}pushMsg({type:"photo",url:finalUrl});setShowEditor(false);setCapturedPhoto("");setEditText("")}
function getFilterStyle(filter:string,beauty:number){let f="";if(filter==="Warm")f="sepia(0.12) saturate(1.08) brightness(1.02)";if(filter==="Cool")f="hue-rotate(8deg) saturate(1.05) brightness(1.02)";if(filter==="Black & White")f="grayscale(1) brightness(1.02)";if(filter==="Vivid")f="saturate(1.15) contrast(1.03) brightness(1.02)";if(filter==="Soft")f="brightness(1.05) contrast(0.98) saturate(0.95)";if(filter==="Natural")f="saturate(1.05) brightness(1.03) contrast(1.02)";if(beauty>0){const b=beauty*0.012;const br=1+b;const ct=1-beauty*0.008;const st=1+beauty*0.012;if(f)f+=" ";f+="brightness("+br.toFixed(3)+") contrast("+ct.toFixed(3)+") saturate("+st.toFixed(3)+")"}return f||"none"}
