function getRealLocation(sendLive=false){if(!navigator.geolocation){alert("GPS not available!");return}navigator.geolocation.getCurrentPosition((pos)=>{const lat=pos.coords.latitude;const lng=pos.coords.longitude;setShowAttach(false);pushMsg({type:"location",lat,lng,live:sendLive,mapUrl:"https://www.google.com/maps?q="+lat+","+lng,embedUrl:"https://www.openstreetmap.org/export/embed.html?bbox="+(lng-0.01)+","+(lat-0.01)+","+(lng+0.01)+","+(lat+0.01)+"&layer=mapnik&marker="+lat+","+lng});if(sendLive)startLiveLocation()},(err)=>{alert("Please allow Location permission!")},{enableHighAccuracy:true,timeout:10000})}
function startLiveLocation(){setLiveLoc(true);if(liveLocTimer.current)clearInterval(liveLocTimer.current);liveLocTimer.current=setInterval(()=>{navigator.geolocation.getCurrentPosition((pos)=>{const lat=pos.coords.latitude;const lng=pos.coords.longitude;pushMsg({type:"location",lat,lng,live:true,mapUrl:"https://www.google.com/maps?q="+lat+","+lng,embedUrl:"https://www.openstreetmap.org/export/embed.html?bbox="+(lng-0.01)+","+(lat-0.01)+","+(lng+0.01)+","+(lat+0.01)+"&layer=mapnik&marker="+lat+","+lng})})},30000);setTimeout(()=>{setLiveLoc(false);if(liveLocTimer.current)clearInterval(liveLocTimer.current)},15*60*1000)}
