function onGalleryPick(e:any){const files=Array.from(e.target.files||[]);if(!files.length)return;const f:any=files[0];if(f.type.startsWith("video")){pushMsg({type:"video",url:URL.createObjectURL(f),time:"Now"});setShowCameraChoice(false);setShowAttach(false);return}const url=URL.createObjectURL(f);openEditor(url)}
function onDocumentPick(e:any){const f=e.target.files[0];if(!f)return;pushMsg({type:"text",text:"Document: "+f.name});setShowAttach(false)}
async function openLiveCamera(){setShowCameraChoice(false);setShowAttach(false);setShowLiveCamera(true);setCapturedPhoto("");setCameraMode("photo");setFilterEffect("None");setBeautyLevel(0);setFacingMode("user");setTorchOn(false);try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"},audio:true});liveStreamRef.current=stream;setTimeout(()=>{if(liveVideoRef.current){liveVideoRef.current.srcObject=stream;liveVideoRef.current.play()}},200)}catch(e){alert("Please allow Camera permission!");setShowLiveCamera(false)}}
async function flipCamera(){if(isFlipping)return;setIsFlipping(true);const nf=facingMode==="user"?"environment":"user";try{const old1=liveStreamRef.current;const old2=streamRef.current;if(old1)old1.getTracks().forEach((t:any)=>{try{t.stop()}catch(e){}});if(old2)old2.getTracks().forEach((t:any)=>{try{t.stop()}catch(e){}});if(liveVideoRef.current)liveVideoRef.current.srcObject=null;if(videoRef.current)videoRef.current.srcObject=null;setTorchOn(false);await new Promise(r=>setTimeout(r,350));let stream=null;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{exact:nf}},audio:true})}catch(e){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:nf},audio:true})}catch(e2){stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true})}}setFacingMode(nf);liveStreamRef.current=stream;streamRef.current=stream;if(showLiveCamera&&liveVideoRef.current){liveVideoRef.current.srcObject=stream;await liveVideoRef.current.play().catch(()=>{})}if(call&&videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play().catch(()=>{})}}catch(e){alert("Back Camera nahi khula! Dobara try karein!");try{const s2=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"},audio:true});setFacingMode("user");liveStreamRef.current=s2;streamRef.current=s2;if(liveVideoRef.current){liveVideoRef.current.srcObject=s2;liveVideoRef.current.play()}if(videoRef.current){videoRef.current.srcObject=s2;videoRef.current.play()}}catch(e){}}setIsFlipping(false)}
function closeLiveCamera(){setTorchOn(false);if(liveStreamRef.current){liveStreamRef.current.getTracks().forEach((t:any)=>t.stop());liveStreamRef.current=null}setShowLiveCamera(false);setCapturedPhoto("");setIsVideoRec(false);setShowEffects(false);if(recTimerSecRef.current)clearInterval(recTimerSecRef.current);setRecTimerSec(0)}
function capturePhoto(){if(!liveVideoRef.current)return;const v=liveVideoRef.current;const c=liveCanvasRef.current;if(!c)return;c.width=v.videoWidth;c.height=v.videoHeight;const ctx=c.getContext("2d");ctx.filter=getFilterStyle(filterEffect,beautyLevel);ctx.drawImage(v,0,0);const url=c.toDataURL("image/jpeg",0.9);openEditor(url)}
function sendCapturedPhoto(){if(!capturedPhoto)return;openEditor(capturedPhoto)}
function startVideoRec(){if(!liveStreamRef.current)return;videoChunks.current=[];const rec=new MediaRecorder(liveStreamRef.current);videoRecRef.current=rec;rec.ondataavailable=(e:any)=>{if(e.data.size>0)videoChunks.current.push(e.data)};rec.onstop=()=>{const blob=new Blob(videoChunks.current,{type:"video/webm"});const reader=new FileReader();reader.onloadend=()=>{pushMsg({type:"video",url:reader.result})};reader.readAsDataURL(blob);closeLiveCamera()};rec.start();setIsVideoRec(true);setRecTimerSec(0);if(recTimerSecRef.current)clearInterval(recTimerSecRef.current);recTimerSecRef.current=setInterval(()=>setRecTimerSec(t=>t+1),1000)}
function stopVideoRec(){if(videoRecRef.current&&isVideoRec){try{videoRecRef.current.stop()}catch(e){}setIsVideoRec(false)}if(recTimerSecRef.current)clearInterval(recTimerSecRef.current)}
async function toggleTorch(){const stream=liveStreamRef.current||streamRef.current;if(!stream){alert("Pehle Back Camera kholein!");return}const track=stream.getVideoTracks()[0];if(!track)return;if(facingMode==="user"){alert("Torch sirf Back Camera par chalti hai! Pehle 🔄 se Back Camera karein!");return}try{const caps:any=track.getCapabilities&&track.getCapabilities();if(caps&&!caps.torch){alert("Is phone me Torch support nahi hai!");return}await track.applyConstraints({advanced:[{torch:!torchOn} as any]});setTorchOn(!torchOn)}catch(e){alert("Torch On nahi hui!")}}
function toggleVoicePlay(idx:number,url:string){if(playingIdx===idx){if(audioRef.current)audioRef.current.pause();setPlayingIdx(null);return}if(audioRef.current)audioRef.current.pause();const a=new Audio(url);audioRef.current=a;a.ontimeupdate=()=>{if(a.duration)setAudioProgress((a.currentTime/a.duration)*100)};a.onended=()=>{setPlayingIdx(null);setAudioProgress(0)};a.play();setPlayingIdx(idx)}
async function startRecording(e:any){if(recording||locked)return;if(isBlocked)return;if(e){e.preventDefault();e.stopPropagation()}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const rec=new MediaRecorder(stream);recRef.current=rec;recChunks.current=[];rec.ondataavailable=(ev:any)=>{if(ev.data.size>0)recChunks.current.push(ev.data)};rec.start(250);setRecording(true);setRecTime(0);setRecHint("");if(recTimer.current)clearInterval(recTimer.current);recTimer.current=setInterval(()=>setRecTime(t=>t+1),1000)}catch(err){alert("Mic permission dein!");setRecording(false)}}
function onMicMove(e:any){if(!recording||locked)return;const t=e.touches?e.touches[0]:e;if(!t)return;const dx=t.clientX-startX.current;const dy=t.clientY-startY.current;if(dx<-60){isCancel.current=true;setRecHint("← Choro to Cancel")}else if(dy<-60){setRecHint("↑ Choro to Lock")}else{isCancel.current=false;setRecHint("")}}
function onMicRelease(e:any){if(!recording)return;if(e)e.preventDefault();const endX=e.changedTouches?e.changedTouches[0].clientX:e.clientX||0;const endY=e.changedTouches?e.changedTouches[0].clientY:e.clientY||0;const dx=endX-startX.current;const dy=endY-startY.current;if(dy<-60){setLocked(true);setRecHint("Locked");return}if(locked)return;if(isCancel.current||dx<-60){finishRecording(false)}else{finishRecording(true)}}
function finishRecording(sendIt:boolean){if(!recRef.current)return;if(recTimer.current)clearInterval(recTimer.current);const rec=recRef.current;const curTime=recTime;rec.onstop=()=>{try{if(rec.stream)rec.stream.getTracks().forEach((t:any)=>t.stop())}catch(e){}if(sendIt&&curTime>0&&recChunks.current.length){const blob=new Blob(recChunks.current,{type:"audio/webm"});const reader=new FileReader();reader.onloadend=()=>{pushMsg({type:"voice",url:reader.result,duration:formatTime(curTime)})};reader.readAsDataURL(blob)}};try{if(rec.state!=="inactive")rec.stop()}catch(e){}setRecording(false);setLocked(false);setRecHint("");isCancel.current=false;setRecTime(0)}
function send(){if(!txt||isBlocked)return;const nm:any={type:"text",text:txt};if(replyTo)nm.reply=replyTo.text||replyTo;pushMsg(nm);setTxt("");setEmojiPanel(false);setReplyTo(null)}
async function startCall(n:string,t:string){setS(n);setCallType(t);setCall(n);setCamOn(true);setMicOn(true);setCallParticipants([]);setShowAddToCall(false);setShowEffects(false);setCallFilter("None");setCallBeauty(0);setFacingMode("user");setTorchOn(false);setCallHistory((prev)=>[{name:n,type:t,dir:"Outgoing",date:"Today",time:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}),duration:"00:00",missed:false},...prev]);if(t==="Video"){try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"},audio:true});streamRef.current=stream;setTimeout(()=>{if(videoRef.current){videoRef.current.srcObject=stream;videoRef.current.play()}},200)}catch(e){alert("Please allow Camera permission!")}}}
function endCall(){setTorchOn(false);if(streamRef.current){streamRef.current.getTracks().forEach((tr:any)=>tr.stop());streamRef.current=null}setCall("");setCallParticipants([]);setShowAddToCall(false);setShowEffects(false)}
function toggleCam(){setCamOn(!camOn);if(streamRef.current)streamRef.current.getVideoTracks().forEach((tr:any)=>tr.enabled=!camOn)}
function toggleMic(){setMicOn(!micOn);if(streamRef.current)streamRef.current.getAudioTracks().forEach((tr:any)=>tr.enabled=!micOn)}
function addPersonToCall(name:string){if(callParticipants.includes(name))return;if(callParticipants.length>=9){alert("Max 10 people!");return}const np=[...callParticipants,name];setCallParticipants(np);setConfMembers(["Adeel",call,...np]);setShowAddToCall(false)}
async function startConfCall(type:"Audio"|"Video"){setConfType(type);setConfCall(true);setConfMembers(["Adeel","Ammi","Bhai","Ayesha","Ali","Sara","My Moti","Khala"]);if(type==="Video"){try{const stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});confStreamRef.current=stream;setTimeout(()=>{if(confVideoRef.current)confVideoRef.current.srcObject=stream},300)}catch(e){alert("Please allow Camera / Mic permission!")}}}
function endConfCall(){if(confStreamRef.current){confStreamRef.current.getTracks().forEach((t:any)=>t.stop());confStreamRef.current=null}setConfCall(false)}
function addToConf(name:string){if(confMembers.includes(name)){setConfMembers(confMembers.filter(x=>x!==name))}else{if(confMembers.length>=10){alert("Max 10 people!");return}setConfMembers([...confMembers,name])}}
function deleteMsg(){if(delIdx===null)return;setMsgs(msgs.filter((_,i)=>i!==delIdx));setDelIdx(null)}
function doBlock(){if(blocked.includes(s))setBlocked(blocked.filter(b=>b!==s));else{setBlocked([...blocked,s]);alert(s+" Blocked")}setShowChatMenu(false)}
